import warnings

import cv2 as cv
import  numpy  as np
import  random
img = np.zeros((800 , 1024 , 3) , np.uint8)
class Bloecke:
    def __init__(self , liste , color  ,  x, y):
        self.schwarz_bloecke_liste = liste
        self.color = color
        self.x = x
        self.y = y

    def draw(self):
        #array = np.array((cols , rows))
        i = 0
        if   0  < self.y  < 800 :
         while i < 3:
            j=0
            while j < 2:
              if (i,j) not in self.schwarz_bloecke_liste:
                block = Block(self.x + (32*i) , self.y + (32*j) ,  self.color )
                block.draw()
              j+=1
            i+=1

    def   move(self , x_reduced , y_reduced):
          self.x += x_reduced
          self.y += y_reduced

class Block:
    def __init__(self , x ,y , color ):
        #  Now we want to define each attributes of our  block (square)
        self.x = x
        self.y = y
        self.color = color
    def  draw(self):
         cv.rectangle(img , (self.x , self.y) , (self.x+30  , self.y+30) , self.color  , -1)

i=0
copie = img
while True:
    if i > 10:
        break
    x = random.randint(50 , 750)
    y = -10
    Liste=[]
    Anzahl_schwarz = random.randint (0,4)
    for i in range(Anzahl_schwarz):
        row= random.randint(0,2)
        col=random.randint(0,2)
        Liste.append((row, col))
    block = Bloecke(Liste, (255, 0, 0), x, y)
    while  block.y  < 800 :
        img = np.zeros((800 , 1024 , 3) , np.uint8)
        block.draw()
        cv.imshow("image", img)
        cv.waitKey(200)
        block.move(0,30)
    i+=1


